function classifyTask(text){const t=normalize(text);if(/image|photo|audio|son|vidéo|video|multim[ée]dia/.test(t))return"multimedia";if(/code|javascript|python|worker|sql|programme/.test(t))return"code";if(/résume|resume|synthèse|synthese/.test(t))return"summary";if(/recherche|source|actualité|actuel|web/.test(t))return"research";if(/mémoire|souvenir|retiens|rappelle/.test(t))return"memory";if(/raisonne|compare|analyse|pourquoi|explique/.test(t))return"reasoning";return"conversation"}
function modelCandidates(task,requested){const effective=TASK_MODEL_ORDER[task]?task:"conversation",ids=TASK_MODEL_ORDER[effective],ordered=requested&&ids.includes(requested)?[requested,...ids.filter(id=>id!==requested)]:ids;return ordered.map(id=>MODEL_REGISTRY.find(m=>m.id===id)).filter(Boolean).slice(0,ORCHESTRATION_LIMITS.max_model_calls)}
function modelChoice(task,requested){return modelCandidates(task,requested)[0]||MODEL_REGISTRY[0]}
function orchestrationStatus(env){return json({version:APP_VERSION,separation:{identity:"Basic Auth/OWNER_NAME",memory:"D1 memories/interactions",skills:"classification and policies",tools:"internal capability registry",models:"Workers AI registry"},models:MODEL_REGISTRY.map(m=>({...m,available:Boolean(env.AI),availability_reason:env.AI?"AI binding configured; runtime verified only after a successful call":"AI binding missing"})),limits:ORCHESTRATION_LIMITS,fallback:{enabled:true,max_attempts:ORCHESTRATION_LIMITS.max_model_calls,clean_failure:true},external_providers:false})}
function orchestrationSelection(env,text,requested){const task=classifyTask(String(text||"")),candidates=modelCandidates(task,requested);return{task,selected_model:candidates[0]&&candidates[0].id||null,candidates:candidates.map(m=>m.id),available:Boolean(env.AI),simulation:true,estimated_max_cost_usd:candidates.reduce((n,m)=>n+m.cost.estimated_max_usd_per_call,0),within_cost_limit:candidates.reduce((n,m)=>n+m.cost.estimated_max_usd_per_call,0)<=ORCHESTRATION_LIMITS.max_estimated_cost_usd}}

