function profInput(v,name){const s=String(v||"").trim();if(!s)throw new ClientError(name+" est requis.","PROFESSOR_INPUT_REQUIRED");if(s.length>20000)throw new ClientError(name+" est trop long.","PROFESSOR_INPUT_TOO_LONG",413);if(secret(s))throw new ClientError("Les secrets ne sont jamais acceptés dans le mode Professeur.","SECRET_REJECTED");return s}
async function professorSession(req,env){const b=await readJson(req),goal=String(b&&b.goal||"");if(secret(goal))throw new ClientError("Les secrets ne sont jamais acceptés.","SECRET_REJECTED");const id=crypto.randomUUID(),now=Date.now();await env.DB.prepare("INSERT INTO professor_sessions(id,created_at,updated_at,last_used_at,status,goal,provenance) VALUES(?,?,?,?,?,?,?)").bind(id,now,now,now,"active",goal.slice(0,2000),"professor_session").run();return json({ok:true,session_id:id,status:"active",stage:"session",next_action:"question"})}
async function professorGet(env,id){const s=await env.DB.prepare("SELECT id,created_at,updated_at,last_used_at,status,goal,provenance FROM professor_sessions WHERE id=?").bind(id).first();if(!s)throw new ClientError("Session professeur introuvable.","PROFESSOR_SESSION_NOT_FOUND",404);const [t,l]=await Promise.all([env.DB.prepare("SELECT id,session_id,created_at,last_used_at,kind,question,answer,confidence,memories_json,tools_json,critique,correction,improved_answer,correction_id,retest_id,passed,explanation_variant,provenance FROM professor_turns WHERE session_id=? ORDER BY id").bind(id).all(),env.DB.prepare("SELECT id,session_id,turn_id,created_at,last_used_at,lesson,rationale,validated,understanding_status,importance,confidence,memory_id,correction_turn_id,retest_id,provenance FROM professor_lessons WHERE session_id=? ORDER BY id").bind(id).all()]);const turns=t.results||[],lessons=l.results||[];return json({session:s,turns,lessons,summary:{turns:turns.length,questions:turns.filter(x=>x.kind==="question").length,retests:turns.filter(x=>x.kind==="retest").length,understood_lessons:lessons.filter(x=>x.understanding_status==="understood").length,pending_lessons:lessons.filter(x=>x.understanding_status!=="understood").length}})}
async function professorAsk(req,env){const b=await readJson(req),sid=profInput(b&&b.session_id,"session_id"),question=profInput(b&&b.question,"question"),s=await env.DB.prepare("SELECT id FROM professor_sessions WHERE id=? AND status='active'").bind(sid).first();if(!s)throw new ClientError("Session professeur introuvable ou terminée.","PROFESSOR_SESSION_NOT_ACTIVE",404);const used=await toolContext(env,question),confidence=used.search_memories.length?0.72:0.48,inference=await askAI(env,b&&b.model,[{role:"system",content:systemPrompt(env.OWNER_NAME||"Adrien",used)+"\nMode Professeur piloté par ChatGPT Work. Réponds clairement et reste honnête."},{role:"user",content:question}]),answer=inference.text,now=Date.now(),r=await env.DB.prepare("INSERT INTO professor_turns(session_id,created_at,last_used_at,kind,question,answer,confidence,memories_json,tools_json,provenance,correction_id,retest_id,passed,explanation_variant) VALUES(?,?,?,?,?,?,?,?,?,?,?,?,?,?)").bind(sid,now,now,"question",question,answer,confidence,JSON.stringify(used.search_memories),JSON.stringify({...used,model_execution:inference}),"professor_question",null,null,null,0).run();await env.DB.prepare("UPDATE professor_sessions SET updated_at=?,last_used_at=? WHERE id=?").bind(now,now,sid).run();return json({ok:true,session_id:sid,turn_id:r.meta&&r.meta.last_row_id||null,stage:"answer",next_action:"correction",answer,confidence,model:inference.model,fallback_used:inference.fallback_used,tool_succeeded:inference.tool_succeeded,memories:used.search_memories,tools:used,sources:used.sources_used||[]})}
async function professorCorrect(req,env){const b=await readJson(req),sid=profInput(b&&b.session_id,"session_id"),tid=Number(b&&b.turn_id),critique=String(b&&b.critique||""),correction=String(b&&b.correction||""),improved=String(b&&b.improved_answer||"");if(!Number.isInteger(tid)||tid<=0)throw new ClientError("turn_id invalide.","PROFESSOR_TURN_INVALID");if(secret(critique)||secret(correction)||secret(improved))throw new ClientError("Les secrets ne sont jamais acceptés.","SECRET_REJECTED");if(!critique.trim()&&!correction.trim()&&!improved.trim())throw new ClientError("Une critique, correction ou meilleure réponse est requise.","PROFESSOR_CORRECTION_REQUIRED");const session=await env.DB.prepare("SELECT id FROM professor_sessions WHERE id=? AND status='active'").bind(sid).first();if(!session)throw new ClientError("Session professeur introuvable ou terminée.","PROFESSOR_SESSION_NOT_ACTIVE",404);const r=await env.DB.prepare("UPDATE professor_turns SET critique=?,correction=?,improved_answer=?,last_used_at=?,correction_id=? WHERE id=? AND session_id=? AND kind='question'").bind(critique.trim()||null,correction.trim()||null,improved.trim()||null,Date.now(),tid,tid,sid).run();if(!r.meta||r.meta.changes!==1)throw new ClientError("Tour professeur introuvable.","PROFESSOR_TURN_NOT_FOUND",404);await env.DB.prepare("UPDATE professor_sessions SET updated_at=?,last_used_at=? WHERE id=?").bind(Date.now(),Date.now(),sid).run();return json({ok:true,session_id:sid,turn_id:tid,stage:"correction",next_action:"lesson",corrected:true})}
async function professorLesson(req,env){const b=await readJson(req),sid=profInput(b&&b.session_id,"session_id"),tid=Number(b&&b.turn_id),lesson=profInput(b&&b.lesson,"lesson"),rationale=String(b&&b.rationale||"");if(!Number.isInteger(tid)||tid<=0)throw new ClientError("turn_id invalide.","PROFESSOR_TURN_INVALID");if(secret(rationale)||secret(lesson))throw new ClientError("Les secrets ne sont jamais acceptés.","SECRET_REJECTED");const t=await env.DB.prepare("SELECT id,critique,correction,improved_answer FROM professor_turns WHERE id=? AND session_id=? AND kind='question'").bind(tid,sid).first();if(!t)throw new ClientError("Tour professeur introuvable.","PROFESSOR_TURN_NOT_FOUND",404);if(!t.critique&&!t.correction&&!t.improved_answer)throw new ClientError("Une correction est requise avant la leçon.","PROFESSOR_CORRECTION_REQUIRED");const duplicate=await env.DB.prepare("SELECT id,memory_id,understanding_status FROM professor_lessons WHERE session_id=? AND turn_id=? AND lesson=?").bind(sid,tid,lesson).first();if(duplicate)return json({ok:true,session_id:sid,lesson_id:duplicate.id,memory_id:duplicate.memory_id||null,duplicate:true,validated:duplicate.understanding_status==="understood",understanding_status:duplicate.understanding_status,stage:"lesson",next_action:"retest"});const now=Date.now(),r=await env.DB.prepare("INSERT INTO professor_lessons(session_id,turn_id,created_at,lesson,rationale,validated,importance,confidence,last_used_at,provenance,correction_turn_id,retest_id,understanding_status,memory_id) VALUES(?,?,?,?,?,?,?,?,?,?,?,?,?,NULL)").bind(sid,tid,now,lesson,rationale,0,1,.5,null,"professor_session_lesson",tid,null,"pending_retest").run(),lessonId=r.meta&&r.meta.last_row_id||null;await env.DB.prepare("UPDATE professor_sessions SET updated_at=?,last_used_at=? WHERE id=?").bind(now,now,sid).run();return json({ok:true,session_id:sid,lesson_id:lessonId,memory_id:null,duplicate:false,validated:false,understanding_status:"pending_retest",stage:"lesson",next_action:"retest"})}
async function professorRetest(req,env){const b=await readJson(req),sid=profInput(b&&b.session_id,"session_id"),question=profInput(b&&b.question||"Réponds à nouveau en appliquant la leçon.","question"),passed=b&&b.passed===true,s=await env.DB.prepare("SELECT id FROM professor_sessions WHERE id=? AND status='active'").bind(sid).first();if(!s)throw new ClientError("Session professeur introuvable ou terminée.","PROFESSOR_SESSION_NOT_ACTIVE",404);const pending=(await env.DB.prepare("SELECT id,lesson,turn_id,confidence FROM professor_lessons WHERE session_id=? AND understanding_status='pending_retest' ORDER BY id DESC LIMIT 1").bind(sid).all()).results||[];const lesson=pending[0];if(!lesson)throw new ClientError("Aucune leçon en attente de retest pour cette session.","PROFESSOR_LESSON_PENDING_REQUIRED",409);const used=await toolContext(env,question),variant=passed?0:1,system=systemPrompt(env.OWNER_NAME||"Adrien",used)+(passed?"\nVérifie la compréhension de la leçon validée.":"\nLe retest a échoué. Donne une explication différente, concrète et plus simple; termine par une nouvelle question de retest."),inference=await askAI(env,b&&b.model,[{role:"system",content:system+"\nLeçon à vérifier:\n"+lesson.lesson},{role:"user",content:question}]),answer=inference.text,now=Date.now(),r=await env.DB.prepare("INSERT INTO professor_turns(session_id,created_at,last_used_at,kind,question,answer,confidence,memories_json,tools_json,provenance,correction_id,retest_id,passed,explanation_variant) VALUES(?,?,?,?,?,?,?,?,?,?,?,?,?,?)").bind(sid,now,now,"retest",question,answer,passed?.88:.4,JSON.stringify(used.search_memories),JSON.stringify({...used,model_execution:inference}),"professor_retest",lesson.turn_id,null,passed?1:0,variant).run(),retestId=r.meta&&r.meta.last_row_id||null;await env.DB.prepare("UPDATE professor_turns SET retest_id=? WHERE id=?").bind(retestId,lesson.turn_id).run();let memoryId=null;if(passed){const mem=await addMemory(env,lesson.lesson,"lesson",1,"professor_retest",{provenance:"professor_retest_passed",professor_session_id:sid,professor_lesson_id:lesson.id,professor_turn_id:lesson.turn_id,retest_id:retestId});memoryId=mem.id;await env.DB.prepare("UPDATE professor_lessons SET validated=1,understanding_status='understood',confidence=?,last_used_at=?,retest_id=?,memory_id=? WHERE id=? AND session_id=?").bind(.88,now,retestId,memoryId,lesson.id,sid).run()}else await env.DB.prepare("UPDATE professor_lessons SET validated=0,understanding_status='retry_required',confidence=?,last_used_at=?,retest_id=? WHERE id=? AND session_id=?").bind(.4,now,retestId,lesson.id,sid).run();await env.DB.prepare("UPDATE professor_sessions SET updated_at=?,last_used_at=? WHERE id=?").bind(now,now,sid).run();return json({ok:true,session_id:sid,turn_id:retestId,lesson_id:lesson.id,answer,confidence:passed?.88:.4,passed,understood:passed,understanding_status:passed?"understood":"retry_required",next_action:passed?"verify_comprehension":"new_retest_with_different_explanation",explanation_variant:variant,memory_id:memoryId,model:inference.model,fallback_used:inference.fallback_used,tool_succeeded:inference.tool_succeeded,memories:used.search_memories,tools:used,sources:used.sources_used||[],lessons:[lesson]})}
async function professorStats(env){const [s,t,q,r,l,p,f]=await Promise.all([env.DB.prepare("SELECT COUNT(*) n FROM professor_sessions").first(),env.DB.prepare("SELECT COUNT(*) n FROM professor_turns").first(),env.DB.prepare("SELECT COUNT(*) n FROM professor_turns WHERE kind='question'").first(),env.DB.prepare("SELECT COUNT(*) n FROM professor_turns WHERE kind='retest'").first(),env.DB.prepare("SELECT COUNT(*) n FROM professor_lessons WHERE understanding_status='understood'").first(),env.DB.prepare("SELECT COUNT(*) n FROM professor_lessons WHERE understanding_status IN ('pending_retest','retry_required')").first(),env.DB.prepare("SELECT COUNT(*) n FROM professor_turns WHERE kind='retest' AND passed=0").first()]);return json({version:APP_VERSION,sessions:Number(s&&s.n)||0,turns:Number(t&&t.n)||0,questions:Number(q&&q.n)||0,retests:Number(r&&r.n)||0,validated_lessons:Number(l&&l.n)||0,understood_lessons:Number(l&&l.n)||0,pending_retests:Number(p&&p.n)||0,failed_retests:Number(f&&f.n)||0,criterion:"understood only after passed retest"})}
const PROFESSOR_PAGE='<html lang="fr"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>MELITURGOS — Professeur</title><style>body{margin:0;background:#0c0c0e;color:#eee;font:16px system-ui}main{max-width:900px;margin:auto;padding:24px 16px}section{background:#151518;border:1px solid #29292f;border-radius:16px;padding:16px;margin:12px 0}.grid{display:grid;gap:8px}textarea,input{width:100%;box-sizing:border-box;background:#101014;color:#fff;border:1px solid #3a3a42;border-radius:10px;padding:11px;margin:6px 0}button{background:#292932;color:#fff;border:1px solid #4a4a55;border-radius:10px;padding:10px;margin:4px;cursor:pointer}.answer,.meta{white-space:pre-wrap;background:#222227;padding:12px;border-radius:10px}.meta{background:transparent;color:#aaa;font-size:13px}</style></head><body><main><p><a href="/" style="color:#aaa">← MELITURGOS</a></p><h1>Mode Professeur / ChatGPT Work</h1><p class="meta">Session guidée sans accès aux secrets, Cloudflare ou déploiement.</p><section><button id="start-session">Démarrer une session</button><input id="session-goal" placeholder="Objectif"><div id="session-id" class="meta"></div></section><section class="grid" id="professor-media"><strong>Médias privés (R2)</strong><input id="professor-media-file" type="file" accept="image/jpeg,image/png,image/webp,audio/webm,audio/wav,audio/mpeg,video/webm,video/mp4"><button id="professor-media-upload" type="button">Envoyer le média</button><div id="professor-media-status" class="meta">Téléversement désactivé jusqu’à validation.</div></section><section class="grid"><textarea id="professor-question" placeholder="Question"></textarea><button id="send-question">Poser la question</button><div id="meliturgos-answer" class="answer"></div><div id="professor-evidence" class="meta"></div></section><section class="grid"><textarea id="professor-critique" placeholder="Critique"></textarea><textarea id="professor-correction" placeholder="Correction"></textarea><textarea id="improved-answer" placeholder="Meilleure réponse"></textarea><button id="send-correction">Envoyer la correction</button><button id="save-lesson">Valider comme leçon</button><textarea id="retest-question" placeholder="Question de retest"></textarea><button id="retest">Nouvelle réponse / retest</button><button id="finish-session">Terminer la session</button><div id="professor-status" class="meta"></div></section><script>const q=s=>document.querySelector(s);let sid=null,tid=null;async function api(p,o){o=o||{};o.headers=Object.assign({"content-type":"application/json"},o.headers||{});const r=await fetch(p,o),t=await r.text();let j;try{j=JSON.parse(t)}catch{throw Error("Réponse non JSON")}if(!r.ok)throw Error(j.error||("HTTP "+r.status));return j}function fail(e){q("#professor-status").textContent="Erreur : "+e.message}q("#start-session").onclick=async()=>{try{const j=await api("/api/professor/session",{method:"POST",body:JSON.stringify({goal:q("#session-goal").value})});sid=j.session_id;q("#session-id").textContent="Session "+sid}catch(e){fail(e)}};q("#send-question").onclick=async()=>{try{if(!sid)throw Error("Démarre une session");const j=await api("/api/professor/ask",{method:"POST",body:JSON.stringify({session_id:sid,question:q("#professor-question").value})});tid=j.turn_id;q("#meliturgos-answer").textContent=j.answer;q("#professor-evidence").textContent="Souvenirs : "+j.memories.length+"\\nOutils : "+Object.keys(j.tools).join(", ")}catch(e){fail(e)}};q("#send-correction").onclick=async()=>{try{await api("/api/professor/correct",{method:"POST",body:JSON.stringify({session_id:sid,turn_id:tid,critique:q("#professor-critique").value,correction:q("#professor-correction").value,improved_answer:q("#improved-answer").value})});q("#professor-status").textContent="Correction enregistrée"}catch(e){fail(e)}};q("#save-lesson").onclick=async()=>{try{const lesson=q("#professor-correction").value||q("#improved-answer").value;if(!sid||!tid||!lesson)throw Error("Correction et tour requis");const j=await api("/api/professor/lesson",{method:"POST",body:JSON.stringify({session_id:sid,turn_id:tid,lesson,rationale:q("#professor-critique").value})});q("#professor-status").textContent="Leçon validée, memory_id="+j.memory_id}catch(e){fail(e)}};q("#retest").onclick=async()=>{try{const j=await api("/api/professor/retest",{method:"POST",body:JSON.stringify({session_id:sid,question:q("#retest-question").value})});tid=j.turn_id;q("#meliturgos-answer").textContent=j.answer;q("#professor-evidence").textContent="Retest · souvenirs : "+j.memories.length+" · leçons : "+j.lessons.length}catch(e){fail(e)}};q("#finish-session").onclick=async()=>{try{if(!sid)throw Error("Aucune session");q("#professor-status").textContent="Session persistée : "+sid;await api("/api/professor/session/"+sid)}catch(e){fail(e)}};q("#professor-media-upload").onclick=()=>{q("#professor-media-status").textContent="Téléversement désactivé : validation R2 requise.";};</script></main></body></html>';
async function professorPage(){const base=html(PROFESSOR_PAGE),body=await base.text(),panel='<section class="grid" id="capability-panel"><h2>Outils et modèles</h2><p class="meta">État réel des capacités. Une capacité indisponible n’est jamais présentée comme exécutée.</p><button id="refresh-capabilities" type="button">Actualiser les capacités</button><div id="capability-list" class="meta">Chargement…</div></section><script>(function(){var list=document.querySelector("#capability-list"),button=document.querySelector("#refresh-capabilities");async function refresh(){list.textContent="Chargement…";try{var registry=await api("/api/tools/registry"),lines=registry.tools.map(function(t){return (t.available?"✓":"○")+" "+t.name+" — "+t.effective_status+" — "+t.capability+"\n  "+t.explanation});list.textContent=lines.join("\n\n")}catch(e){list.textContent="Registre indisponible : "+e.message}}button.onclick=refresh;refresh()})();</script>';return new Response(body.replace("</main>",panel+"</main>"),{status:base.status,headers:base.headers})}
const professorPageWithKnowledge=professorPage;professorPage=async function(){const base=await professorPageWithKnowledge(),body=await base.text(),panel='<section class="grid" id="knowledge-panel"><h2>Knowledge contrôlé</h2><p class="meta">Sources et imports restent privés, textuels et révocables. Aucune source n’est active sans autorisation explicite.</p><input id="knowledge-source-id" placeholder="ID source"><button id="knowledge-load" type="button">Charger source/import</button><button id="knowledge-revoke" type="button">Révoquer la source</button><div id="knowledge-state" class="meta">Aucune source chargée</div><script>(function(){var id=document.querySelector("#knowledge-source-id"),state=document.querySelector("#knowledge-state");document.querySelector("#knowledge-load").onclick=async function(){try{if(!id.value.trim())throw Error("ID source requis");var s=await api("/api/knowledge/source/"+encodeURIComponent(id.value.trim())),i=await api("/api/knowledge/import/"+encodeURIComponent(id.value.trim()));state.textContent="Source : "+s.source.name+" · statut "+s.source.status+" · confiance "+s.source.confidence+"\nImports : "+(i.import?i.import.status:"introuvable")+" · erreurs : "+(i.import?i.import.error||"aucune":"-")}catch(e){state.textContent="Knowledge indisponible : "+e.message}};document.querySelector("#knowledge-revoke").onclick=async function(){try{if(!id.value.trim())throw Error("ID source requis");var r=await api("/api/knowledge/source/"+encodeURIComponent(id.value.trim())+"/revoke",{method:"POST",body:JSON.stringify({})});state.textContent="Source révoquée logiquement : "+r.status}catch(e){state.textContent="Révocation refusée : "+e.message}}})();</script></section>';return new Response(body.replace("</main>",panel+"</main>"),{status:base.status,headers:base.headers})}
function manifest(){return new Response(JSON.stringify({name:"MELITURGOS",short_name:"MELITURGOS",start_url:"/",display:"standalone",background_color:"#0c0c0e",theme_color:"#0c0c0e",description:"IA personnelle persistante"}),{headers:{"content-type":"application/manifest+json"}})}

const PAGE=`<!doctype html><html lang="fr"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1,viewport-fit=cover"><meta name="theme-color" content="#0c0c0e"><link rel="manifest" href="/manifest.webmanifest"><title>MELITURGOS Cloud</title><style>
:root{font-family:Inter,system-ui,-apple-system,Segoe UI,Roboto,sans-serif;color-scheme:dark}*{box-sizing:border-box}body{margin:0;background:#0c0c0e;color:#eee}main{max-width:980px;margin:auto;padding:20px 16px 100px}header{display:flex;justify-content:space-between;gap:12px;align-items:flex-end;margin-bottom:16px}h1{font-size:clamp(28px,5vw,44px);margin:0;letter-spacing:.04em}.tag{color:#9aa0a9;margin:4px 0 0}.status{font-size:13px;color:#9aa0a9;text-align:right}.panel{background:#151518;border:1px solid #29292f;border-radius:18px;box-shadow:0 12px 40px #0005}#chat{padding:16px;min-height:48vh;max-height:65vh;overflow:auto}.msg{white-space:pre-wrap;line-height:1.52;padding:12px 14px;border-radius:15px;margin:10px 0;overflow-wrap:anywhere}.user{background:#20304b;margin-left:10%}.bot{background:#222227;margin-right:5%}.meta{font-size:11px;color:#93939c;margin-top:8px}.feedback{display:flex;gap:7px;margin:6px 0 14px}button,select,input,textarea{font:inherit}button{border:1px solid #3a3a42;background:#24242a;color:#fff;border-radius:12px;padding:10px 13px;cursor:pointer}.small{padding:6px 9px;font-size:12px}.composer{position:sticky;bottom:8px;margin-top:12px;padding:10px;display:grid;grid-template-columns:1fr auto;gap:8px}textarea{resize:none;min-height:76px;background:#0f0f12;color:#fff;border:1px solid #34343c;border-radius:13px;padding:12px}.toolbar{display:flex;gap:8px;flex-wrap:wrap;margin:10px 0}select,input{background:#17171b;color:#eee;border:1px solid #34343c;border-radius:10px;padding:8px}details{margin-top:14px;padding:14px}.row{display:flex;gap:8px;flex-wrap:wrap}.row input{flex:1;min-width:180px}.badge{display:inline-block;border:1px solid #3b3b44;border-radius:999px;padding:3px 8px;font-size:11px;color:#aaa}.error{color:#ff9b9b}@media(max-width:600px){main{padding:12px 10px 80px}header{align-items:flex-start}.status{font-size:11px}.user{margin-left:5%}.bot{margin-right:0}#chat{min-height:54vh}}
</style></head><body><main><header><div><h1>MELITURGOS</h1><p class="tag">Cloud v0.2.2 · mémoire persistante · mobile</p></div><div class="status" id="status">connexion…</div></header><div class="toolbar"><select id="model"><option value="@cf/zai-org/glm-4.7-flash">GLM 4.7 Flash — défaut</option><option value="@cf/google/gemma-3-12b-it">Gemma 3 12B</option><option value="@cf/meta/llama-3.3-70b-instruct-fp8-fast">Llama 3.3 70B</option></select><button class="small" id="backup">Sauvegarder la mémoire</button><button class="small" id="diagnostic">Diagnostic</button></div><div id="diag" class="meta"></div><section class="panel" id="chat"></section><form class="panel composer" id="form"><textarea id="q" placeholder="Parle à MELITURGOS…" autofocus></textarea><button type="submit">Envoyer</button></form><details class="panel"><summary>Éducation / mémoire manuelle</summary><p>Ajoute une connaissance à conserver durablement.</p><div class="row"><select id="kind"><option>fact</option><option>identity</option><option>preference</option><option>decision</option><option>project</option><option>episodic</option><option>lesson</option></select><input id="remember" placeholder="Ce qu’il doit retenir…"><button id="rememberBtn">Mémoriser</button></div></details><details class="panel"><summary>Importer GENESIS</summary><p>Sélectionne un export GENESIS JSON. Les doublons sont ignorés.</p><input type="file" id="importFile" accept=".json,application/json"><button id="importBtn">Importer</button><div id="importStatus" class="meta"></div></details><script>
var qs=function(s){return document.querySelector(s)},chat=qs('#chat'),q=qs('#q');async function api(path,options){options=options||{};var h=new Headers(options.headers||{});if(options.body&&!h.has('content-type'))h.set('content-type','application/json');options.headers=h;var r;try{r=await fetch(path,options)}catch(e){throw new Error('Connexion impossible au service MELITURGOS.')}var raw=await r.text(),data;try{data=raw?JSON.parse(raw):{}}catch(e){var p=raw.replace(/<[^>]*>/g,' ').replace(/\\s+/g,' ').trim().slice(0,160);throw new Error('Le serveur a répondu en '+r.status+' avec un format non JSON'+(p?' : '+p:''))}if(!r.ok)throw new Error(data.error||('Erreur HTTP '+r.status));return data}
function add(text,cls,meta,iid){var d=document.createElement('div');d.className='msg '+cls;d.textContent=text;if(meta){var m=document.createElement('div');m.className='meta';m.textContent=meta;d.appendChild(m)}chat.appendChild(d);if(iid){var f=document.createElement('div'),y=document.createElement('button'),n=document.createElement('button');f.className='feedback';y.className=n.className='small';y.textContent='👍 utile';n.textContent='👎 corriger';y.onclick=async function(){try{await api('/api/feedback',{method:'POST',body:JSON.stringify({interaction_id:iid,good:true})});f.innerHTML='<span class="badge">retour enregistré</span>'}catch(e){f.textContent='Erreur : '+e.message}};n.onclick=async function(){var c=prompt('Quelle correction doit-il retenir ?','');if(c===null)return;try{await api('/api/feedback',{method:'POST',body:JSON.stringify({interaction_id:iid,good:false,correction:c})});f.innerHTML='<span class="badge">correction prioritaire mémorisée</span>'}catch(e){f.textContent='Erreur : '+e.message}};f.append(y,n);chat.appendChild(f)}chat.scrollTop=chat.scrollHeight}
async function refresh(){try{var s=await api('/api/status');qs('#status').textContent=s.memories+' souvenirs · '+s.interactions+' échanges · en ligne'}catch(e){qs('#status').textContent='erreur : '+e.message}}qs('#form').onsubmit=async function(e){e.preventDefault();var text=q.value.trim();if(!text)return;q.value='';add(text,'user');var w=document.createElement('div');w.className='msg bot';w.textContent='MELITURGOS réfléchit…';chat.appendChild(w);try{var j=await api('/api/chat',{method:'POST',body:JSON.stringify({text:text,model:qs('#model').value})});w.remove();add(j.text,'bot',j.model+' · '+j.memory_hits+' souvenirs retrouvés',j.interaction_id);refresh()}catch(err){w.classList.add('error');w.textContent='Erreur : '+err.message}};q.addEventListener('keydown',function(e){if(e.key==='Enter'&&!e.shiftKey){e.preventDefault();qs('#form').requestSubmit()}});qs('#rememberBtn').onclick=async function(e){e.preventDefault();var c=qs('#remember').value.trim();if(!c)return;try{var j=await api('/api/remember',{method:'POST',body:JSON.stringify({content:c,kind:qs('#kind').value,importance:.9})});qs('#remember').value='';refresh();alert(j.duplicate?'Souvenir déjà présent.':'Souvenir enregistré.')}catch(err){alert('Erreur : '+err.message)}};qs('#backup').onclick=function(){location.href='/api/export'};qs('#diagnostic').onclick=async function(){var d=qs('#diag');d.textContent='Diagnostic en cours…';try{var j=await api('/api/diagnostic');d.textContent='v'+j.version+' · D1 '+j.checks.d1+' · AI '+j.checks.ai_binding+' · auth '+j.checks.authentication+' · '+j.latency_ms+' ms'}catch(e){d.textContent='Erreur : '+e.message}};qs('#importBtn').onclick=async function(){var f=qs('#importFile').files[0];if(!f)return;try{var j=await api('/api/import',{method:'POST',body:JSON.stringify(JSON.parse(await f.text()))});qs('#importStatus').textContent=j.imported+' ajoutés · '+j.duplicates+' doublons ignorés · '+j.rejected+' rejetés';refresh()}catch(e){qs('#importStatus').textContent='Erreur : '+e.message}};add('Je suis MELITURGOS Cloud v0.2.2. Ma mémoire persistante est prête.','bot','mémoire D1');refresh();
</script></main></body></html>`;

export default{async fetch(request,env){const url=new URL(request.url),isApi=url.pathname.startsWith("/api");if(url.pathname==="/manifest.webmanifest")return manifest();if(!env.MELITURGOS_PASSWORD)return isApi?json({error:"MELITURGOS n'est pas configuré.",code:"AUTH_NOT_CONFIGURED"},503):html("<h1>MELITURGOS non configuré</h1>",503);if(!authorized(request,env))return isApi?json({error:"Authentification MELITURGOS requise",code:"AUTH_REQUIRED"},401,{"WWW-Authenticate":'Basic realm="MELITURGOS"'}):new Response("Authentification MELITURGOS requise",{status:401,headers:{"WWW-Authenticate":'Basic realm="MELITURGOS"'}});try{await initDB(env);if(request.method==="GET"&&url.pathname==="/")return html(PAGE);if(request.method==="GET"&&(url.pathname==="/professor"||url.pathname==="/professor/"))return await professorPage();if(request.method==="GET"&&url.pathname==="/api/status")return await status(env);if(request.method==="GET"&&url.pathname==="/api/diagnostic")return await diagnostic(env);if(request.method==="GET"&&url.pathname==="/api/export")return await exportData(env);if(request.method==="POST"&&url.pathname==="/api/chat")return await chat(request,env);if(request.method==="POST"&&url.pathname==="/api/voice/transcribe")return await voiceTranscribe(request,env);if(request.method==="POST"&&url.pathname==="/api/voice/speak")return await voiceSpeak(request,env);if(request.method==="POST"&&url.pathname==="/api/feedback")return await feedback(request,env);if(request.method==="POST"&&url.pathname==="/api/remember")return await remember(request,env);if(request.method==="POST"&&url.pathname==="/api/import")return await importData(request,env);if(request.method==="POST"&&url.pathname==="/api/professor/session")return await professorSession(request,env);if(request.method==="POST"&&url.pathname==="/api/professor/ask")return await professorAsk(request,env);if(request.method==="POST"&&url.pathname==="/api/professor/correct")return await professorCorrect(request,env);if(request.method==="POST"&&url.pathname==="/api/professor/lesson")return await professorLesson(request,env);if(request.method==="POST"&&url.pathname==="/api/professor/retest")return await professorRetest(request,env);if(request.method==="GET"&&url.pathname.startsWith("/api/professor/session/"))return await professorGet(env,url.pathname.slice(23));if(request.method==="GET"&&url.pathname==="/api/professor/stats")return await professorStats(env);if(request.method==="POST"&&url.pathname==="/api/knowledge/source")return await knowledgeSource(request,env);if(request.method==="POST"&&url.pathname==="/api/knowledge/import")return await knowledgeImport(request,env);if(request.method==="GET"&&url.pathname==="/api/knowledge/search")return await knowledgeSearch(request,env);if(request.method==="GET"&&url.pathname.startsWith("/api/knowledge/source/")&&!url.pathname.endsWith("/revoke"))return await knowledgeSourceGet(env,url.pathname.slice(22));if(request.method==="POST"&&url.pathname.startsWith("/api/knowledge/source/")&&url.pathname.endsWith("/revoke"))return await knowledgeControl(request,env,url.pathname.slice(22,-7),"revoke");if(request.method==="POST"&&url.pathname.startsWith("/api/knowledge/import/")&&(url.pathname.endsWith("/pause")||url.pathname.endsWith("/resume")||url.pathname.endsWith("/cancel")))return await knowledgeImportControl(request,env,url.pathname.slice(22,-url.pathname.split("/").pop().length-1),url.pathname.split("/").pop());if(request.method==="GET"&&url.pathname.startsWith("/api/knowledge/import/"))return await knowledgeImportGet(env,url.pathname.slice(22));if((request.method==="GET"||request.method==="POST")&&url.pathname==="/api/learning/profile")return await learningProfile(request,env);if(request.method==="GET"&&url.pathname==="/api/learning/progress")return await learningProgress(env);if(request.method==="POST"&&url.pathname==="/api/learning/topic")return await learningTopic(request,env);if(request.method==="POST"&&url.pathname==="/api/learning/review")return await learningReview(request,env);if(request.method==="POST"&&url.pathname.startsWith("/api/learning/lesson/"))return await learningLessonStatus(request,env,Number(url.pathname.slice(22)));if(request.method==="GET"&&url.pathname==="/api/learning/export")return await learningExport(env);if(request.method==="POST"&&url.pathname==="/api/media/upload")return await mediaUpload(request,env);if(request.method==="GET"&&url.pathname.startsWith("/api/media/"))return await mediaGet(env,url.pathname.slice(11));if(request.method==="DELETE"&&url.pathname.startsWith("/api/media/"))return await mediaDelete(request,env,url.pathname.slice(11));if(request.method==="POST"&&url.pathname==="/api/tasks")return await taskEndpoint(request,"create");if(request.method==="GET"&&url.pathname==="/api/tasks/status")return await taskEndpoint(request,"status");if(request.method==="POST"&&url.pathname==="/api/tasks/emergency")return await taskEndpoint(request,"emergency");if(request.method==="POST"&&url.pathname.startsWith("/api/tasks/"))return await taskEndpoint(request,url.pathname.endsWith("/pause")?"pause":url.pathname.endsWith("/resume")?"resume":url.pathname.endsWith("/stop")?"stop":"unknown",url.pathname.slice(11).split("/")[0]);if(request.method==="GET"&&url.pathname.startsWith("/api/tools/"))return await tools(request,env,url.pathname.slice(11));return isApi?json({error:"Route API inconnue.",code:"NOT_FOUND"},404):html("<h1>Page introuvable</h1>",404)}catch(e){if(e instanceof ClientError)return json({error:e.message,code:e.code},e.status);console.error(JSON.stringify({message:"request failed",path:url.pathname,error:e instanceof Error?e.message:String(e)}));return isApi?json(publicError(e),500):html("<h1>Service temporairement indisponible</h1>",500)}}};
// evaluation tool extension is exposed through the existing read-only tools route
async function tools(req,env,name){const u=new URL(req.url);if(name==="registry")return toolRegistry(env);if(name==="governance/status")return governanceStatus();if(name==="orchestration/status")return orchestrationStatus(env);if(name==="orchestration/select")return json(orchestrationSelection(env,u.searchParams.get("q")||"",u.searchParams.get("model")||null));if(name==="media/status")return mediaStatus(env);if(name.startsWith("evaluation/session/"))return evaluateSession(env,name.slice(19));if(name==="connectors/registry")return connectorRegistry();if(name.startsWith("connectors/")&&name.endsWith("/status"))return connectorStatus(name.slice(11,-7));if(name.startsWith("connectors/")&&name.endsWith("/usage"))return connectorUsage(name.slice(11,-6));if(name==="memory_count")return json({tool:name,result:await memoryCount(env)});if(name==="interaction_count")return json({tool:name,result:await interactionCount(env)});if(name==="search_memories")return json({tool:name,result:await searchMemories(env,u.searchParams.get("q")||"",u.searchParams.get("limit"))});if(name==="recent_interactions")return json({tool:name,result:await recentInteractions(env,u.searchParams.get("limit"))});if(name==="memory_by_topic")return json({tool:name,result:await memoryByTopic(env,u.searchParams.get("topic")||"",u.searchParams.get("limit"))});throw new ClientError("Outil interne inconnu.","UNKNOWN_TOOL",404)}
async function knowledgeImportGet(env,id){const r=await env.DB.prepare("SELECT id,source_id,status,idempotency_key,created_at,updated_at,passage_count,error FROM knowledge_imports WHERE id=?").bind(id).first();if(!r)throw new ClientError("Import introuvable.","IMPORT_NOT_FOUND",404);return json({import:r})}
async function knowledgeForPrompt(env,q){const n=normalize(q);if(!n)return[];const like="%"+n.split(" ").filter(Boolean).slice(0,5).join("%")+"%";const r=await env.DB.prepare("SELECT p.id,p.source_id,p.title,p.text,p.source_date,p.confidence,s.name,s.author,s.url FROM knowledge_passages p JOIN knowledge_sources s ON s.id=p.source_id WHERE p.active=1 AND s.status='active' AND lower(p.text) LIKE ? ORDER BY p.confidence DESC,p.source_date DESC LIMIT 6").bind(like).all();return(r.results||[]).map(x=>({passage_id:x.id,source_id:x.source_id,title:x.title,text:x.text,confidence:Number(x.confidence)||0,source:x.name,author:x.author,url:x.url,date:x.source_date,citation:"knowledge_sources/"+x.source_id+"#passage-"+x.id}))}
